-- Staging: trim identifiers/text, retain source values, normalize status casing.
CREATE OR REPLACE VIEW stg.accounts AS SELECT NULLIF(TRIM(account_id),'') account_id, NULLIF(TRIM(borrower_id),'') borrower_id, UPPER(TRIM(status)) account_status, NULLIF(TRIM(risk_segment),'') risk_segment, NULLIF(TRIM(loan_type),'') loan_type, NULLIF(TRIM(timezone),'') account_timezone, NULLIF(TRIM(schema_version),'') schema_version, NULLIF(TRIM(dpd),'')::integer dpd, NULLIF(TRIM(outstanding_amount),'')::numeric(18,2) outstanding_amount, NULLIF(TRIM(principal_amount),'')::numeric(18,2) principal_amount, opened_at::timestamp opened_at FROM raw.accounts;
CREATE OR REPLACE VIEW stg.payments AS SELECT NULLIF(TRIM(payment_id),'') payment_id, NULLIF(TRIM(account_id),'') account_id, NULLIF(TRIM(borrower_id),'') event_borrower_id, event_at::timestamp event_at_source, NULLIF(TRIM(payment_reference),'') payment_reference, NULLIF(TRIM(amount),'')::numeric(18,2) amount, UPPER(TRIM(payment_status)) payment_status, UPPER(TRIM(payment_method)) payment_method, NULLIF(TRIM(provider_id),'') provider_id FROM raw.payments;
CREATE OR REPLACE VIEW stg.calls AS SELECT NULLIF(TRIM(call_id),'') call_id, NULLIF(TRIM(account_id),'') account_id, NULLIF(TRIM(borrower_id),'') event_borrower_id, event_at::timestamp event_at_source, NULLIF(TRIM(agent_id),'') agent_id, NULLIF(TRIM(campaign_id),'') campaign_id, NULLIF(TRIM(vendor_id),'') vendor_id, UPPER(TRIM(direction)) direction, UPPER(TRIM(call_status)) call_status, NULLIF(TRIM(duration_sec),'')::integer duration_sec, NULLIF(TRIM(timezone),'') source_timezone FROM raw.calls;
CREATE OR REPLACE VIEW stg.targeting AS SELECT NULLIF(TRIM(target_id),'') target_id, NULLIF(TRIM(account_id),'') account_id, NULLIF(TRIM(campaign_id),'') campaign_id, target_date::date target_date, DATE_TRUNC('month',target_date::timestamp)::date month_start, NULLIF(TRIM(priority),'')::integer priority, UPPER(TRIM(recommended_channel)) recommended_channel, UPPER(TRIM(status)) targeting_status FROM raw.daily_targeting;
-- Other event tables retain raw event_at and IDs; apply same trim/upper rules in the load job.
